import{_ as i,C as n,o as r,c as l,a6 as t,E as a}from"./chunks/framework.5dd0l9Wo.js";const b=JSON.parse('{"title":"Authentication","description":"Enumeration, brute-force protection, 2FA state machines, password reset poisoning, and cookie cracking.","frontmatter":{"title":"Authentication","description":"Enumeration, brute-force protection, 2FA state machines, password reset poisoning, and cookie cracking."},"headers":[],"relativePath":"authentication/index.md","filePath":"authentication/index.md"}'),c={name:"authentication/index.md"};function d(u,e,h,p,m,f){const s=n("LabGroup"),o=n("TopicComplete");return r(),l("div",null,[e[0]||(e[0]=t('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p class="wd-section-lede">Authentication is a state machine built from credentials, cookies, reset tokens, and second factors. Most authentication bugs are not broken cryptography — they are a step the server forgets to verify, or a signal that tells the attacker which guess was closer.</p><div class="wd-callout"><p><strong>The model.</strong> A login is a comparison plus a session assignment. Every additional flow — reset, remember-me, 2FA, email change — is another path to the same session. Test each path independently and test the transitions between them.</p></div><h2 id="enumeration-the-response-is-an-oracle" tabindex="-1">Enumeration: the response is an oracle <a class="header-anchor" href="#enumeration-the-response-is-an-oracle" aria-label="Permalink to &quot;Enumeration: the response is an oracle&quot;">​</a></h2><p>Before brute force, determine which usernames exist. Applications leak this through:</p><ul><li><strong>Different error text:</strong> &quot;Invalid username&quot; vs &quot;Incorrect password&quot;.</li><li><strong>Subtle differences:</strong> a trailing space, different punctuation, a different redirect.</li><li><strong>Timing:</strong> password hashing only happens for valid users, so a valid username takes longer.</li><li><strong>Account lockout:</strong> a valid account locks after N failures; an invalid one never does.</li><li><strong>Registration and reset forms:</strong> &quot;email already in use&quot; is an enumeration oracle too.</li></ul>',6)),a(s,{ids:"authentication-lab-username-enumeration-via-different-responses, authentication-lab-username-enumeration-via-subtly-different-responses, authentication-lab-username-enumeration-via-response-timing, authentication-lab-username-enumeration-via-account-lock"}),e[1]||(e[1]=t(`<details class="details custom-block"><summary>🔬 Under the Hood: why timing reveals valid users</summary><p>A typical login does:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user = lookup(username)</span></span>
<span class="line"><span>if not user: return &quot;invalid credentials&quot;          # fast</span></span>
<span class="line"><span>if not bcrypt.check(password, user.hash): return   # ~100 ms</span></span>
<span class="line"><span>return session</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The invalid-username path skips the deliberately expensive hash. The difference is measurable even with network noise if you repeat and compare distributions rather than single requests. Constant-time responses require hashing a dummy password when the user does not exist.</p></details><h2 id="brute-force-and-its-protections" tabindex="-1">Brute force and its protections <a class="header-anchor" href="#brute-force-and-its-protections" aria-label="Permalink to &quot;Brute force and its protections&quot;">​</a></h2><p>Rate limits and lockouts are state machines too. Common failures:</p><ul><li>counting failures per IP, so rotating <code>X-Forwarded-For</code> resets the counter;</li><li>locking the account but not the IP, enabling a denial-of-service or an enumeration signal;</li><li>limiting requests but accepting many credentials in one request;</li><li>trusting a client-side counter or a cookie.</li></ul>`,4)),a(s,{ids:"authentication-lab-broken-bruteforce-protection-ip-block, authentication-lab-broken-brute-force-protection-multiple-credentials-per-request"}),e[2]||(e[2]=t('<h2 id="second-factors" tabindex="-1">Second factors <a class="header-anchor" href="#second-factors" aria-label="Permalink to &quot;Second factors&quot;">​</a></h2><p>2FA is often bolted on after the password step, with the session already partially authenticated. If the application sets a &quot;logged in&quot; cookie before the second factor, or lets the client choose which account is being verified, the factor is decorative.</p><ul><li><strong>Simple bypass:</strong> navigate directly to an authenticated page after the password step.</li><li><strong>Broken logic:</strong> the <code>verify</code> endpoint trusts a client-supplied username and does not bind the code to a pending session.</li><li><strong>Brute force:</strong> a four-digit code with no attempt limit falls in minutes.</li></ul>',3)),a(s,{ids:"authentication-lab-2fa-simple-bypass, authentication-lab-2fa-broken-logic, authentication-lab-2fa-bypass-using-a-brute-force-attack"}),e[3]||(e[3]=t('<details class="details custom-block"><summary>🔬 Under the Hood: the pending-authentication state</summary><p>A safe 2FA flow keeps a server-side <code>pending_user</code> in the session and refuses every other route until the second factor succeeds. A vulnerable flow either:</p><ol><li>issues the real session cookie after the password and merely <em>shows</em> the 2FA form, or</li><li>stores the pending user in a client-visible parameter (<code>verify=wiener</code>) that the attacker can change.</li></ol><p>Both are state-machine bugs. The code may be cryptographically strong and still irrelevant.</p></details><h2 id="remember-me-cookies-and-offline-cracking" tabindex="-1">Remember-me cookies and offline cracking <a class="header-anchor" href="#remember-me-cookies-and-offline-cracking" aria-label="Permalink to &quot;Remember-me cookies and offline cracking&quot;">​</a></h2><p>A &quot;stay logged in&quot; cookie often contains <code>username:hash(password)</code> in base64. If the hash is MD5 or SHA-1 without a salt, it is crackable offline with a wordlist — no rate limit, no server logs.</p>',3)),a(s,{ids:"authentication-lab-brute-forcing-a-stay-logged-in-cookie, authentication-lab-offline-password-cracking"}),e[4]||(e[4]=t('<h2 id="password-reset-flows" tabindex="-1">Password reset flows <a class="header-anchor" href="#password-reset-flows" aria-label="Permalink to &quot;Password reset flows&quot;">​</a></h2><p>Reset is an authentication path that bypasses the password entirely. Test:</p><ul><li>whether the token is validated at all (<code>temp-forgot-password-token</code> missing or empty);</li><li>whether the token is bound to the user or reusable;</li><li>whether the reset link is built from a client-controlled <code>Host</code> header;</li><li>whether the change-password form checks the current password and the username consistently.</li></ul>',3)),a(s,{ids:"authentication-lab-password-reset-broken-logic, authentication-lab-password-reset-poisoning-via-middleware, authentication-lab-password-brute-force-via-password-change"}),e[5]||(e[5]=t('<details class="details custom-block"><summary>⚙️ Engine Variations: token generation by framework</summary><ul><li><strong>Django:</strong> <code>default_token_generator</code> hashes the user&#39;s PK, password, last-login, and timestamp with the secret key; tokens expire and invalidate on password change.</li><li><strong>Rails:</strong> <code>has_secure_token</code> produces a random 24-character token; <code>reset_password_token</code> is stored hashed in the database.</li><li><strong>PHP frameworks:</strong> often use <code>bin2hex(random_bytes(32))</code>; the bug is usually binding, not entropy.</li><li><strong>JWT-based reset:</strong> if the token is a JWT signed with a weak key and no audience check, it can be forged or replayed across environments.</li></ul><p>Entropy is rarely the weak point. Binding and expiry are.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Use a vetted identity library. Hash passwords with Argon2id or bcrypt. Return identical responses and comparable timing for unknown users. Rate-limit per account and per IP. Keep the pre-2FA session unauthenticated. Bind reset tokens to the user, hash them at rest, expire them, and make them single-use. Build absolute URLs from configuration, never from the Host header.</p></div>',2)),a(o,{"topic-id":"authentication",label:"Mark authentication complete"})])}const _=i(c,[["render",d]]);export{b as __pageData,_ as default};
